"""SearXNG's secret key: generated by setup, never the shipped placeholder.

``deploy/searxng/settings.yml`` and ``docker-compose.yml`` ship one placeholder
``secret_key`` (SearXNG signs its cookies and image-proxy links with it), and
compose falls back to it when ``SEARXNG_SECRET`` is unset, so a one-command
``docker compose --profile search up -d searxng`` still works for someone who
never ran setup. The owner's decision (2026-11-11): setup generates one rather
than asking the owner to.

* ``kazma setup install``'s step before it starts SearXNG
  (``container_services.ensure_secret``, SearXNG's row): keep ``SEARXNG_SECRET`` in the install's ``.env`` (the file
  compose reads) when it holds none, through
  ``env_files.persist_generated_secret`` (the file restricted to this account
  before the value is written). A value already there -- the owner's, or one
  an earlier run generated -- is never replaced; the placeholder is not a
  value.
* :func:`uses_placeholder` -- whether a running SearXNG container's key is the
  placeholder, from ``docker inspect``: its ``SEARXNG_SECRET`` (which wins
  over settings.yml), else the ``server.secret_key`` of the settings.yml it
  mounts. ``security.service_exposure`` says it at boot and in the security
  report. A value is only compared, never logged.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any

__all__ = ["PLACEHOLDER", "SECRET_VAR", "uses_placeholder"]

#: The placeholder settings.yml and docker-compose.yml ship.
PLACEHOLDER = "change-me-in-production-use-long-random"
#: The variable compose passes to the container (SearXNG's own name).
SECRET_VAR = "SEARXNG_SECRET"
#: compose's label naming the folder a container's project was started from.
_COMPOSE_DIR_LABEL = "com.docker.compose.project.working_dir"
#: Where the compose service mounts deploy/searxng.
_SETTINGS_MOUNT = "/etc/searxng"


def _set(value: str | None) -> bool:
    """A real key: something other than empty or the placeholder."""
    text = (value or "").strip().strip('"').strip("'")
    return bool(text) and text != PLACEHOLDER


def _settings_key(text: str) -> str | None:
    import yaml

    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError:
        return None
    server = data.get("server") if isinstance(data, dict) else None
    key = server.get("secret_key") if isinstance(server, dict) else None
    return str(key) if key is not None else None


def _mounted_settings(info: dict[str, Any]) -> Path | None:
    """The settings.yml the container reads, on this machine, if it can be found."""
    labels = (info.get("Config") or {}).get("Labels") or {}
    project = labels.get(_COMPOSE_DIR_LABEL) if isinstance(labels, dict) else None
    candidates = []
    if project:
        candidates.append(Path(project) / "deploy" / "searxng" / "settings.yml")
    for mount in info.get("Mounts") or []:
        if isinstance(mount, dict) and mount.get("Destination") == _SETTINGS_MOUNT and mount.get("Source"):
            candidates.append(Path(str(mount["Source"])) / "settings.yml")
    for path in candidates:
        if path.is_file():
            return path
    return None


def uses_placeholder(info: dict[str, Any]) -> bool | None:
    """Whether the container ``docker inspect`` described runs with the
    placeholder key: True, False, or None when it cannot be told."""
    env = (info.get("Config") or {}).get("Env") or []
    for item in env:
        name, sep, value = str(item).partition("=")
        if sep and name == SECRET_VAR and value.strip():
            return value.strip() == PLACEHOLDER
    settings = _mounted_settings(info)
    if settings is None:
        return None
    try:
        key = _settings_key(settings.read_text(encoding="utf-8"))
    except OSError:
        return None
    return None if key is None else not _set(key)
